def test_every_map_shape_has_country_data(self):
    world = load("countries-110m.json")
    numerics = {c["numeric"] for c in COUNTRIES.values()}
    ids = [g.get("id") for g in world["objects"]["countries"]["geometries"]]
    missing = [i for i in ids if i is not None and i not in numerics]
    self.assertEqual(missing, [], "map shapes without country data")

def test_shares_between_0_and_100(self):
    for iso2, c in COUNTRIES.items():
        for l in c["langs"]:
            self.assertTrue(0 <= l["pct"] <= 100, f"{iso2}/{l['code']}={l['pct']}")

def test_no_placeholder_or_variant_codes(self):
    for iso2, c in COUNTRIES.items():
        for l in c["langs"]:
            self.assertNotIn(l["code"], ("und", "zxx"), iso2)
            self.assertNotIn("_", l["code"], f"{iso2}: script/region variant not merged (R1)")

def test_population_series_complete_and_positive(self):
    n = META["years"][1] - META["years"][0] + 1
    for iso2, c in COUNTRIES.items():
        self.assertEqual(len(c["pop"]), n, iso2)
        self.assertTrue(all(p is not None and p >= 0 for p in c["pop"]), iso2)

def test_every_inhabited_country_has_a_region(self):
    no_region = [k for k, c in COUNTRIES.items() if not c["region"] and c["pop"][-1] > 0 and k != "AQ"]
    self.assertEqual(no_region, [])

def test_known_facts(self):
    mx = {l["code"]: l for l in COUNTRIES["MX"]["langs"]}
    self.assertGreater(mx["es"]["pct"], 80)  # CLDR 46 lists 83%
    ca = {l["code"]: l for l in COUNTRIES["CA"]["langs"]}
    self.assertIn(ca["en"]["official"], ("official", "de_facto_official"))
    self.assertIn(ca["fr"]["official"], ("official", "de_facto_official"))
    self.assertEqual(COUNTRIES["FR"]["langs"][0]["code"], "fr")
    self.assertEqual(COUNTRIES["US"]["region"], "Americas")
    self.assertEqual(COUNTRIES["IN"]["subregion"], "Southern Asia")

def test_speaker_totals_near_reference(self):
    for code, ref in self.REFERENCE.items():
        ratio = LANGUAGES[code]["speakers"] / ref
        self.assertTrue(0.65 <= ratio <= 1.35, f"{code}: {LANGUAGES[code]['speakers']:.3g} vs {ref:.3g}")

def test_major_languages_have_family(self):
    expect = {"en": "Indo-European", "zh": "Sino-Tibetan", "ar": "Afro-Asiatic", "sw": "Atlantic-Congo", "ja": "Japonic"}
    for code, fam in expect.items():
        self.assertEqual(LANGUAGES[code].get("family"), fam, code)

def test_every_language_named(self):
    unnamed = [c for c, l in LANGUAGES.items() if not l["name"] or l["name"] == c]
    self.assertLess(len(unnamed), 0.05 * len(LANGUAGES), unnamed[:20])

def test_known_gaps_filled(self):
    for iso2, low in {"JP": 15, "NO": 70, "ID": 15, "UA": 30, "RU": 1}.items():
        l = self.share(iso2, "en")
        self.assertIsNotNone(l, f"{iso2} has no English figure")
        self.assertGreaterEqual(l["pct"], low, iso2)

def test_wikipedia_never_lowers_a_cldr_share(self):
    for iso2, c in COUNTRIES.items():
        for l in c["langs"]:
            if l.get("src") == "wikipedia" and l["cldr_pct"] is not None:
                self.assertGreater(l["pct"], l["cldr_pct"], f"{iso2}/{l['code']}")

def test_wikipedia_revisions_pinned(self):
    for lang, w in META["wikipedia"].items():
        self.assertIsInstance(w["revid"], int, lang)
        self.assertGreater(w["countries"], 20, lang)

def test_years_extend_to_projection(self):
    self.assertEqual(META["years"], [1960, 2026])
    self.assertEqual(META["projected_from"], 2025)

def test_projection_continues_recent_trend(self):
    for iso2 in ("IN", "NG", "JP", "US"):
        pop = COUNTRIES[iso2]["pop"]
        recent, projected = pop[64] / pop[59], pop[66] / pop[64]
        self.assertAlmostEqual(projected, recent ** 0.4, places=3, msg=iso2)

def test_dialect_counts_consistent(self):
    for gid, e in self.INDEX.items():
        self.assertEqual(e[7], len(self.DIALECTS.get(gid, [])), gid)

def test_anchor_series_well_formed(self):
    for s in ANCHORS["series"]:
        key = f"{s['country']}/{s['lang']}"
        self.assertIn(s["country"], COUNTRIES, key)
        for field in ("metric", "source", "confidence"):
            self.assertTrue(s.get(field), f"{key} missing {field}")
        self.assertIn(s["confidence"], ("high", "medium", "low"), key)
        years = [p[0] for p in s["points"]]
        self.assertEqual(years, sorted(set(years)), f"{key} years not strictly increasing")
        self.assertTrue(all(0 <= p[1] <= 100 for p in s["points"]), key)

def test_anchored_languages_flagged_in_countries(self):
    for s in ANCHORS["series"]:
        flagged = [l for l in COUNTRIES[s["country"]]["langs"] if l["code"] == s["lang"]]
        self.assertTrue(flagged and flagged[0].get("anchored"), f"{s['country']}/{s['lang']}")

def test_checked_in_output_matches_fresh_build(self):
    with tempfile.TemporaryDirectory() as a:
        build.build(a)
        for name in ("countries.json", "languages.json"):
            self.assertEqual((Path(a) / name).read_bytes(), (DATA / name).read_bytes(), f"{name} is stale; run pipeline/build.py")

def test_major_countries_have_regions(self):
    for iso2 in ("US", "ES", "IT", "IN", "FR", "GB", "CN", "BR"):
        self.assertGreater(self.INDEX[iso2]["regions"], 10, iso2)

def test_every_curated_share_lands_on_a_region(self):
    curated = json.loads((ROOT / "pipeline" / "regional_shares.json").read_text(encoding="utf8"))["series"]
    unmatched = META["regions"]["unmatched_shares"]
    for s in curated:
        self.assertNotIn(f"{s['country']}/{s['region']}", unmatched)

def test_known_regions(self):
    es = {r["name"]: r for r in self.regions("ES")}
    self.assertEqual([(s["lang"], s["pct"]) for s in es["Barcelona"]["shares"]], [("ca", 81.2)])
    self.assertIn("eu", [s["lang"] for s in es["Gipuzkoa"]["shares"]])
    gindex = load("glottolog_index.json")
    sicily = {gindex[g][0] for r in self.regions("IT") if r["parent"] == "Sicily" for g in r["langs"]}
    self.assertIn("Sicilian", sicily)

def test_shares_in_range_and_sourced(self):
    for iso2 in self.INDEX:
        for r in self.regions(iso2):
            for s in r["shares"]:
                self.assertTrue(0 <= s["pct"] <= 100, f"{iso2}/{r['name']}")
                self.assertTrue(s["source"] and s["metric"], f"{iso2}/{r['name']}")

def test_rings_closed_and_wound_for_d3(self):
    import regions as admin1
    for iso2 in ("ES", "US", "ID"):
        for r in self.regions(iso2):
            for poly in r["geom"]:
                for i, ring in enumerate(poly):
                    self.assertEqual(ring[0], ring[-1], r["name"])
                    self.assertEqual(admin1.area(ring) < 0, i == 0, f"{r['name']} ring {i} winding")

def test_learning_links_are_https_and_typed(self):
    learn = load("learn.json")
    self.assertGreater(len(learn), 150)
    for code, e in learn.items():
        for r in e["resources"]:
            self.assertTrue(r["url"].startswith("https://"), r["url"])
            self.assertIn(r["kind"], ("course", "textbook", "dictionary", "reference"))
        h = e.get("hello")
        if h:
            self.assertTrue(h["word"], code)
            if "audio" in h:
                self.assertTrue(h["audio"].startswith("https://upload.wikimedia.org/"), h["audio"])

def test_session_totals_equal_sum_of_calls(self):
    self.assertGreaterEqual(len(self.t["sessions"]), 1)
    for s in self.t["sessions"]:
        for k in ("in", "out", "cw", "cr"):
            self.assertEqual(s["totals"][k], sum(c[k] for c in s["calls"]), (s["id"], k))
        self.assertEqual(s["totals"]["calls"], len(s["calls"]))
        self.assertEqual(s["totals"]["peak_ctx"], max(c["ctx"] for c in s["calls"]))

def test_calls_have_known_step_and_prompt(self):
    steps = {x["id"] for x in self.t["steps"]}
    for s in self.t["sessions"]:
        for c in s["calls"]:
            self.assertIn(c["step"], steps)
            self.assertTrue(0 <= c["p"] < len(s["prompts"]))
            self.assertEqual(c["ctx"], c["in"] + c["cw"] + c["cr"])

def test_unrelated_sessions_excluded(self):
    ids = {s["id"] for s in self.t["sessions"]}
    for e in self.t["excluded"]:
        self.assertNotIn(e["id"], ids)

def test_provenance_fields(self):
    for d in (self.v, self.t):
        self.assertTrue(d["source"])
        self.assertTrue(d["method"])

def test_run_counts_match_test_log(self):
    runs = {r["id"]: r for r in self.v["runs"]}
    self.assertEqual(set(runs), {r["run_id"] for r in self.results})
    for rid, run in runs.items():
        rows = [r for r in self.results if r["run_id"] == rid]
        self.assertEqual(run["pass"], sum(r["status"] == "pass" for r in rows), rid)
        self.assertEqual(run["fail"], sum(r["status"] != "pass" for r in rows), rid)

def test_every_test_in_latest_run_has_source(self):
    latest = self.v["runs"][-1]["id"]
    shown = {t["id"]: t for t in self.v["tests"]}
    for r in self.results:
        if r["run_id"] == latest:
            self.assertIn(r["test"], shown)
            self.assertIn("def " if r["suite"] == "python" else "test(", shown[r["test"]]["code"])

test("interpolate holds flat outside anchors and is linear inside", () => {
  const pts = [[1980, 10], [2000, 30]];
  assert.equal(L.interpolate(pts, 1960), 10);
  assert.equal(L.interpolate(pts, 1990), 20);
  assert.equal(L.interpolate(pts, 2024), 30);
  assert.equal(L.interpolate([[2000, 5]], 1990), 5);
});

test("popAt clamps to the series", () => {
  const c = { pop: Array.from({ length: 65 }, (_, i) => i) };
  assert.equal(L.popAt(c, 1960), 0);
  assert.equal(L.popAt(c, 1950), 0);
  assert.equal(L.popAt(c, 2024), 64);
  assert.equal(L.popAt(c, 2100), 64);
});

test("shareAt tags provenance: measured on anchor years, estimated between, derived without anchors", () => {
  assert.equal(L.shareAt("XX", "aa", 50, 1980, idx).provenance, "measured");
  const mid = L.shareAt("XX", "aa", 50, 1990, idx);
  assert.equal(mid.provenance, "estimated");
  assert.equal(mid.pct, 20);
  const plain = L.shareAt("XX", "bb", 80, 1990, idx);
  assert.deepEqual([plain.pct, plain.provenance], [80, "derived"]);
});

test("breakdown sorts by share and computes speakers", () => {
  const b = L.breakdown("XX", countries.XX, 1990, idx);
  assert.deepEqual(b.map((l) => l.code), ["bb", "aa"]);
  assert.equal(b[0].speakers, 800);
  assert.equal(b[1].speakers, 200);
});

test("multilingualIndex sums shares", () => {
  close(L.multilingualIndex([{ pct: 100 }, { pct: 35 }]), 1.35);
  assert.equal(L.multilingualIndex([]), 0);
});

test("reachability: single language equals its share", () => {
  const r = L.reachability([{ code: "aa", pct: 50 }], [{ code: "aa", level: "native" }]);
  close(r.estimate, 0.5);
  assert.equal(r.best, "aa");
});

test("reachability: two languages combine under independence with bounds", () => {
  const r = L.reachability([{ code: "aa", pct: 50 }, { code: "bb", pct: 50 }],
    [{ code: "aa", level: "fluent" }, { code: "bb", level: "fluent" }]);
  close(r.estimate, 0.75);
  close(r.low, 0.5);
  close(r.high, 1);
});

test("reachability: level weights and unknown languages", () => {
  const r = L.reachability([{ code: "aa", pct: 100 }], [{ code: "aa", level: "basic" }, { code: "zz", level: "native" }]);
  close(r.estimate, 0.4);
  assert.equal(L.reachability([], [{ code: "aa", level: "native" }]).estimate, 0);
});

test("reachability: estimate always within [low, high]", () => {
  const langs = [{ code: "a", pct: 70 }, { code: "b", pct: 40 }, { code: "c", pct: 90 }];
  const mine = [{ code: "a", level: "conversational" }, { code: "b", level: "basic" }, { code: "c", level: "native" }];
  const r = L.reachability(langs, mine);
  assert.ok(r.low <= r.estimate + 1e-12 && r.estimate <= r.high + 1e-12);
});

test("reachability: lists your languages that have no figure in the country", () => {
  const r = L.reachability([{ code: "aa", pct: 40 }], [{ code: "aa", level: "fluent" }, { code: "zz", level: "fluent" }]);
  assert.deepEqual(r.missing, ["zz"]);
  close(r.estimate, 0.4);
  assert.deepEqual(L.reachability([{ code: "aa", pct: 40 }], [{ code: "aa", level: "fluent" }]).missing, []);
});

test("formatPct never prints a non-zero share as 0%", () => {
  assert.equal(L.formatPct(0.004), "<0.01%");
  assert.equal(L.formatPct(0.7), "0.70%");
  assert.equal(L.formatPct(3.75), "3.8%");
  assert.equal(L.formatPct(28), "28%");
  assert.equal(L.formatPct(0), "0%");
  assert.equal(L.formatPct(null), "–");
});

test("searchByName ranks prefix matches before substring matches", () => {
  const items = [{ name: "Swiss German" }, { name: "German" }, { name: "Low German" }, { name: "French" }];
  assert.deepEqual(L.searchByName(items, "germ").map((i) => i.name), ["German", "Swiss German", "Low German"]);
  assert.deepEqual(L.searchByName(items, "  "), []);
  assert.equal(L.searchByName(items, "e", 2).length, 2);
});

test("languageTotal sums speakers across countries and ranks them", () => {
  const t = L.languageTotal(countries, "bb", 2024, idx);
  assert.equal(t.speakers, 1300);
  assert.deepEqual(t.where.map((w) => w.iso2), ["XX", "YY"]);
});

test("topLanguages ranks by speakers and respects anchors", () => {
  const top = L.topLanguages(countries, 2024, idx, 3);
  assert.deepEqual(top.map((t) => t.code), ["bb", "aa", "cc"]);
  assert.equal(top[1].speakers, 300); // anchored aa = 30% in 2024
});

test("regionSummary: second languages exclude each country's main language", () => {
  const s = L.regionSummary(Object.entries(countries), 2024, idx);
  assert.equal(s.pop, 1500);
  assert.deepEqual(s.second.map((d) => d.code).sort(), ["aa", "cc"]);
  close(s.index, (800 + 300 + 500 + 100) / 1500);
});

test("livingLanguagesAt counts extinct languages only up to their last documentation", () => {
  const rows = [["A", "f", null, null], ["B", "f", "extinct", 1980], ["C", "f", "extinct", null], ["D", "f", "moribund", null]];
  assert.equal(L.livingLanguagesAt(rows, 1970), 3);
  assert.equal(L.livingLanguagesAt(rows, 1980), 3);
  assert.equal(L.livingLanguagesAt(rows, 1981), 2);
});

